import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW, PANEL_SHADOW, STYLE } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const MoodMatchCard: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const S = frame.width / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;

  const match = String(p.match ?? anim.text ?? "Playful");
  const moods = Array.isArray(p.moods) && (p.moods as unknown[]).length > 0
    ? (p.moods as unknown[]).map((m) => String(m))
    : ["Cinematic", "Dramatic", "Playful", "Calm"];
  const eyebrow = String(p.eyebrow ?? "Track mood");
  const note = String(p.note ?? "Pixabay · free for commercial use");

  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;
  const radius = STYLE.sharp ? 0 : 30 * S;
  const pillRadius = STYLE.sharp ? 0 : 999;

  const clamp = (v: number) => Math.max(0, Math.min(1, v));

  // card entrance
  const cardIn = spring({ frame: f, fps, config: { damping: 17, mass: 0.7 } });
  const cardY = interpolate(cardIn, [0, 1], [70 * S, 0]);
  const cardO = clamp(f / 8);

  // headline pop
  const headIn = spring({ frame: f - 12, fps, config: { damping: 14, mass: 0.6 } });
  const headScale = interpolate(headIn, [0, 1], [0.82, 1]);

  // lock-in of the matching mood
  const lock = interpolate(f, [54, 72], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const pulse = 1 + 0.02 * Math.sin((f - 60) / 5) * lock;

  const cardW = frame.width * 0.78;

  const headSize = Math.min(
    frame.width * 0.17,
    (frame.width * 0.72) / Math.max(4, match.length * 0.47)
  );

  const bars = 34;

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: cardW,
          transform: `translateY(${cardY}px) scale(${pulse})`,
          opacity: cardO,
          background: COLORS.vellum,
          border: `${Math.max(1, 1.5 * S)}px solid rgba(255,255,255,0.10)`,
          boxShadow: PANEL_SHADOW,
          borderRadius: radius,
          padding: `${44 * S}px ${40 * S}px ${38 * S}px`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 26 * S,
        }}
      >
        {/* eyebrow */}
        <div
          style={{
            fontFamily: FONTS.body,
            fontWeight: 600,
            fontSize: 22 * S,
            letterSpacing: "0.24em",
            textTransform: "uppercase",
            color: muted,
            opacity: clamp((f - 4) / 8),
            textAlign: "center",
          }}
        >
          {eyebrow}
        </div>

        {/* waveform */}
        <div
          style={{
            width: "100%",
            height: 150 * S,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 6 * S,
          }}
        >
          {new Array(bars).fill(0).map((_, i) => {
            const grow = clamp((f - 4 - i * 0.5) / 9);
            const wobble =
              0.28 +
              0.72 *
                Math.abs(
                  Math.sin(f * 0.17 + i * 0.55) * (0.55 + 0.45 * Math.sin(i * 1.7 + 0.6))
                );
            const h = 18 * S + 128 * S * wobble * grow;
            return (
              <div
                key={i}
                style={{
                  width: 10 * S,
                  height: h,
                  borderRadius: STYLE.sharp ? 0 : 999,
                  background: `linear-gradient(180deg, ${COLORS.tealBright}, ${COLORS.teal})`,
                  opacity: 0.45 + 0.55 * grow,
                }}
              />
            );
          })}
        </div>

        {/* matched mood headline */}
        <div
          style={{
            transform: `scale(${headScale})`,
            opacity: clamp((f - 10) / 8),
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: headSize,
            lineHeight: 0.95,
            textTransform: "uppercase",
            textAlign: "center",
            maxWidth: "100%",
            wordBreak: "break-word",
            ...(STYLE.headline === "gradient"
              ? {
                  backgroundImage: headlineGradient(),
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                  color: "transparent",
                }
              : { color: COLORS.teal, textShadow: ENGRAVE_SHADOW }),
          }}
        >
          {match}
        </div>

        {/* mood chips */}
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            gap: 14 * S,
            width: "100%",
          }}
        >
          {moods.map((m, i) => {
            const isMatch = m.trim().toLowerCase() === match.trim().toLowerCase();
            const inT = spring({ frame: f - (24 + i * 6), fps, config: { damping: 15, mass: 0.5 } });
            const dim = isMatch ? 1 : interpolate(lock, [0, 1], [1, 0.3]);
            return (
              <div
                key={i}
                style={{
                  transform: `translateY(${interpolate(inT, [0, 1], [22 * S, 0])}px) scale(${
                    isMatch ? interpolate(lock, [0, 1], [1, 1.08]) : 1
                  })`,
                  opacity: inT * dim,
                  padding: `${12 * S}px ${26 * S}px`,
                  borderRadius: pillRadius,
                  border: isMatch
                    ? `${Math.max(1, 2 * S)}px solid ${COLORS.teal}`
                    : `${Math.max(1, 1.5 * S)}px solid rgba(255,255,255,0.14)`,
                  background: isMatch ? `${COLORS.teal}22` : "rgba(255,255,255,0.05)",
                  color: isMatch ? COLORS.tealBright : muted,
                  fontFamily: FONTS.body,
                  fontWeight: 600,
                  fontSize: 26 * S,
                  letterSpacing: "0.08em",
                  textTransform: "uppercase",
                  whiteSpace: "nowrap",
                }}
              >
                {m}
              </div>
            );
          })}
        </div>
      </div>

      {/* license note */}
      <div
        style={{
          marginTop: 34 * S,
          opacity: clamp((f - 66) / 12) * 0.9,
          fontFamily: FONTS.mono,
          fontSize: 22 * S,
          letterSpacing: "0.14em",
          color: muted,
          textAlign: "center",
          maxWidth: frame.width * 0.8,
        }}
      >
        {note}
      </div>
    </AbsoluteFill>
  );
};

export default MoodMatchCard;
